 void tree(AccessibilityNodeInfo n,JSONArray out,int depth)throws Exception{if(n==null||depth>18||out.length()>=350)return;Rect r=new Rect();n.getBoundsInScreen(r);if(n.isVisibleToUser()){JSONObject o=new JSONObject();o.put("text",n.getText()==null?"":n.getText().toString());o.put("description",n.getContentDescription()==null?"":n.getContentDescription().toString());o.put("hint",n.getHintText()==null?"":n.getHintText().toString());o.put("id",n.getViewIdResourceName()==null?"":n.getViewIdResourceName());o.put("bounds",r.toShortString());o.put("editable",n.isEditable());out.put(o);}for(int i=0;i<n.getChildCount();i++)tree(n.getChild(i),out,depth+1);}
